package dev.odin.controls;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;import java.io.*;
/** Normal-app action dispatcher. Privileged window only renders and sends requests. */
public final class TilePopupService extends Service {
 static Runnable fallback;private final Handler handler=new Handler(Looper.getMainLooper());private File folder;private boolean fan,ready,failureHandled;private volatile boolean stopping;private volatile int rootPid;private long offset,started,lastProbe;private String last="";private final java.util.concurrent.ExecutorService io=java.util.concurrent.Executors.newSingleThreadExecutor();
 static boolean supported(String model,int sdk){return (model.equals("Odin2")&&sdk==33)||(model.equals("Odin3")&&sdk==35);}
 static void open(Context c,boolean fan,Runnable standard){fallback=standard;try{c.startForegroundService(new Intent(c,TilePopupService.class).putExtra("fan",fan));}catch(Exception e){android.util.Log.w("RavenPopup","Chooser service unavailable",e);fallback=null;standard.run();}}
 @Override public void onCreate(){super.onCreate();getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("tile-popup","Profile chooser",NotificationManager.IMPORTANCE_LOW));}
 @Override public int onStartCommand(Intent intent,int flags,int id){
  startForeground(3,new Notification.Builder(this,"tile-popup").setSmallIcon(getResources().getIdentifier("ic_notification","drawable",getPackageName())).setContentTitle("Raven profile chooser").setContentText("Profile chooser is open").build());
  if(intent==null||folder!=null){stopSelf();return START_NOT_STICKY;}fan=intent.getBooleanExtra("fan",false);started=SystemClock.uptimeMillis();
  try{folder=new File(getExternalFilesDir(null),"tile-popup-"+java.util.UUID.randomUUID().toString());if(!folder.mkdirs())throw new IOException("Cannot prepare chooser");for(String f:new String[]{"events","ready","log"})new FileOutputStream(new File(folder,f)).close();writeConfig();
   File script=new File(folder,"launch.sh");String command="CLASSPATH="+Root.q(getApplicationInfo().sourceDir)+" /system/bin/app_process /system/bin dev.odin.controls.RootTilePopup "+Root.q(folder.getPath())+" "+android.os.Process.myPid()+" >"+Root.q(new File(folder,"log").getPath())+" 2>&1 </dev/null &\necho OK $!\n";try(FileOutputStream out=new FileOutputStream(script)){out.write(command.getBytes("UTF-8"));}
   handler.post(poll);io.execute(()->{try{String answer=Root.call("sh "+Root.q(script.getPath()));if(!answer.matches("OK [0-9]+"))throw new IOException("Window helper did not start");rootPid=Integer.parseInt(answer.substring(3));if(rootPid<=1)throw new IOException("Invalid helper PID");if(stopping)killHelper(rootPid);}catch(Exception e){handler.post(()->failed(e));}});
  }catch(Exception e){failed(e);}return START_NOT_STICKY;
 }
 private void failed(Exception e){if(stopping||failureHandled)return;failureHandled=true;android.util.Log.w("RavenPopup","Privileged chooser unavailable",e);Runnable r=fallback;fallback=null;if(r!=null)try{r.run();}catch(Exception fallbackError){android.util.Log.w("RavenPopup","Standard chooser unavailable",fallbackError);android.widget.Toast.makeText(this,"Open Raven System Control to select a profile",1).show();}else android.widget.Toast.makeText(this,"Could not open the profile chooser",1).show();stopSelf();}
 private final Runnable poll=new Runnable(){public void run(){if(stopping)return;try{
  if(new File(folder,"ready").length()>0){ready=true;}
  if(!ready&&SystemClock.uptimeMillis()-started>8000){failed(new IOException("Window helper timed out"));return;}
  try(RandomAccessFile events=new RandomAccessFile(new File(folder,"events"),"r")){events.seek(offset);String line;while((line=events.readLine())!=null){offset=events.getFilePointer();if(line.length()>4096)throw new IOException("Invalid chooser event");JSONObject event=new JSONObject(new String(line.getBytes("ISO-8859-1"),"UTF-8"));String action=event.optString("action");if(action.equals("close")){if(!ready)failed(new IOException("Window helper could not display chooser"));else{fallback=null;stopping=true;stopSelf();}return;}try{if(action.equals("profile")){String name=event.getString("name");if(!ProfileActions.names(TilePopupService.this,fan).contains(name))throw new IOException("Profile is no longer available");ProfileActions.apply(TilePopupService.this,fan,name);}else if(action.equals("power"))ProfileActions.power(TilePopupService.this,fan,event.getBoolean("enabled"));else if(action.equals("group")&&!fan)ProfileActions.groups(TilePopupService.this,event.getBoolean("analog"),event.getBoolean("enabled"));}catch(Exception e){android.widget.Toast.makeText(TilePopupService.this,e.getMessage(),1).show();}}}
  writeConfig();
  if(SystemClock.uptimeMillis()-lastProbe>3000&&rootPid>0){lastProbe=SystemClock.uptimeMillis();io.execute(()->{try{if(!Root.read("test -d /proc/"+rootPid+" && echo alive").trim().equals("alive"))handler.post(()->failed(new IOException("Window helper exited unexpectedly")));}catch(Exception e){handler.post(()->failed(e));}});}
 }catch(Exception e){failed(e);return;}handler.postDelayed(this,250);}};
 private void writeConfig()throws Exception{android.content.SharedPreferences p=getSharedPreferences("profile",0);String active=fan?DeviceState.fan(this):DeviceState.led(this);if(fan&&(active.equals("Quiet")||active.equals("Smart")||active.equals("Sport")))active+=" · stock";JSONObject j=new JSONObject().put("fan",fan).put("separateGroups",Build.MODEL.equals("Odin2")).put("heartbeat",SystemClock.uptimeMillis()/1000).put("names",new JSONArray(ProfileActions.names(this,fan))).put("active",active).put("analog",ProfileActions.groupOn(this,true)).put("side",ProfileActions.groupOn(this,false)).put("busy",!fan&&LedProfileService.isApplying()).put("light",p.getString("appearanceMode","dark").equals("light")).put("accent",p.getInt("accentColor",0xffff8000));String value=j.toString();if(value.equals(last))return;File tmp=new File(folder,"config.new");try(FileOutputStream out=new FileOutputStream(tmp)){out.write(value.getBytes("UTF-8"));}if(!tmp.renameTo(new File(folder,"config.json")))throw new IOException("Cannot update chooser");last=value;}
 private static void killHelper(int pid){if(pid<=1)return;try{Root.call("if tr '\\0' ' ' </proc/"+pid+"/cmdline | grep -q dev.odin.controls.RootTilePopup;then kill "+pid+";fi");}catch(Exception ignored){}}
 @Override public void onDestroy(){stopping=true;handler.removeCallbacksAndMessages(null);if(rootPid>0){final int pid=rootPid;io.execute(()->killHelper(pid));}io.shutdown();stopForeground(STOP_FOREGROUND_REMOVE);super.onDestroy();}
 @Override public IBinder onBind(Intent i){return null;}
}
